import React from 'react'

export default function Card() {
    return (
        <div>
            <div>
                <div className="card mt-3 ml-3" style={{ "width": "18rem", "font-family": "cursive", "maxHeight": "460px" }}>
                    <img src="https://images.unsplash.com/photo-1621996346565-e3dbc646d9a9?w=500&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8NHx8cGFzdGF8ZW58MHx8MHx8fDA%3D" className="card-img-top" alt="..." />
                    <div className="card-body">
                        <h5 className="card-title">Card title</h5>
                        <p className="card-text">Some quick example text to build  card's content.</p>
                        <div className='container w-100'>
                            <select className='m-2 h-60  bg-success rounded'>
                                {Array.from(Array(6), (e, i) => {
                                    return (
                                        <option key={i + 1} value={i + 1}> {i + 1} </option>
                                    )
                                })}
                            </select>
                            <select className='-2 h-60  bg-success rounded' style={{justifyItems:"left"}}>
                                <option value='half'>Half</option>
                                <option value='full'>Full</option>
                            </select>
                            <div className='d-inline h-100 fs-6 m-3'>Total Price</div>
                        </div>

                    </div>
                </div>
            </div>

        </div>
    )
}
